const EMAIL = 'brendon@iangroup.vc';
const ANGEL = 'IAN Group - Angel Fund';
const ALPHA = 'IAN Group - Alpha Fund';

// Already shared with IAN per Deal Tracker row 212 - excluded from BOTH funds.
const TRACKER = ['AI Signal Labs','CLIKD','Desi Machines','EosNox','MindWox','Outlanders','Starz AI','Vira Jal','Washtro'];

const A = [["Body & Beyond","Aditya",88],["Fire Armor","Chaman",88],["Formverse","Akansha",88],["Fydo","Shradha",88],["Koncite","Akansha",88],["MonitorExam","Aditya",88],["Opulytics","Akansha",88],["Springbase.ai","Akansha",88],["bezgoFresh","Chaman",88],["ServeAmigo","Shradha",80],["Appli","Akansha",76],["Chayan Karo","Shradha",76],["Doffair","Chaman",76],["Indie Stori","Aditya",76],["Orbis Lives","Chaman",76],["Pixelence","Akansha",76],["SureChain","Shradha",76],["Vilva AI","Shradha",76],["Xproguard","Akansha",76],["Caffena Coffee","Aditya",73],["EkoSight","Chaman",73],["Ela Greens","Chaman",73],["Glazia Windoors","Chaman",73],["LUSTR","Aditya",73],["Lex Protector","Akansha",73],["Road Athena","Chaman",73],["Shippin","Chaman",73],["Sugar's Daddy","Aditya",73]];
const B = [["Flyment","Chaman",100],["LearningPad","Aditya",100],["MentorCloud","Shradha",100],["Orbo AI","Shradha",100],["Talent Recruit","Akansha",88],["Ulai","Shradha",88],["Alt F Coworking","Chaman",85]];

function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

// Both funds share Brendon's inbox, so a startup already sitting under EITHER IAN row is a
// duplicate for the other fund too. Exclude by startup, not by (startup, investor) pair.
const seenStartup = {};
for (const r of rows) {
  if (s(r.investor).toLowerCase().indexOf('ian group') === 0) { seenStartup[s(r.startup).toLowerCase()] = true; }
}
for (const t of TRACKER) { seenStartup[t.toLowerCase()] = true; }

let maxN = 0;
for (const r of rows) {
  const id = s(r.deal_id);
  if (id.charAt(0) === 'D') { const n = parseInt(id.slice(1), 10); if (!isNaN(n) && n > maxN) { maxN = n; } }
}
if (maxN === 0) { throw new Error('ABORT: could not determine max deal_id'); }

// weekday-only dates from Tue 8 Sep, two per fund per day
function weekdays(n, y, m, d) {
  const out = []; const dt = new Date(Date.UTC(y, m - 1, d));
  while (out.length < n) {
    const wd = dt.getUTCDay();
    if (wd !== 0 && wd !== 6) { out.push(dt.toISOString().slice(0, 10)); }
    dt.setUTCDate(dt.getUTCDate() + 1);
  }
  return out;
}

let n = maxN;
const out = [];
const FUNDS = [{ name: ANGEL, list: A }, { name: ALPHA, list: B }];
for (const f of FUNDS) {
  const keep = f.list.filter(function (x) { return !seenStartup[x[0].toLowerCase()]; });
  const days = weekdays(Math.ceil(keep.length / 2) + 1, 2026, 9, 8);
  for (let i = 0; i < keep.length; i++) {
    const startup = keep[i][0], owner = keep[i][1], score = keep[i][2];
    n++;
    let pad = String(n);
    while (pad.length < 5) { pad = '0' + pad; }
    out.push({ json: {
      deal_id: 'D' + pad,
      startup: startup,
      owner: owner,
      investor: f.name,
      email: EMAIL,
      cc: '',
      priority: score,
      deal_shared: 'No',
      next_action: 'Initial',
      next_due: days[Math.floor(i / 2)],
      notes: (score >= 85 ? 'Very High' : 'High') + ' match (' + score + ') - ' + f.name + ' split mandate 2026-09-07'
    }});
  }
}

if (out.length === 0) { throw new Error('ABORT: 0 new rows - all candidates already exist'); }
if (out.length > 35) { throw new Error('ABORT: ' + out.length + ' exceeds guard of 35'); }
return out;
